def f(g):
    h,w=len(g),len(g[0])
    # find top bar
    bar=None
    for j in range(w):
        if g[0][j]!=0:
            if bar is None: bar=[j,j]
            bar[1]=j
    colors={g[0][j]:j for j in range(bar[0],bar[1]+1)}
    # lone cells of each color elsewhere
    lone={}
    for i in range(h):
        for j in range(w):
            v=g[i][j]
            if i>0 or not (bar[0]<=j<=bar[1]):
                if v!=0: lone.setdefault(v,(i,j))
    out=[[0]*w for _ in range(h)]
    for j in range(bar[0],bar[1]+1):
        out[0][j]=g[0][j]
    for v,j in colors.items():
        if v in lone:
            ti,tj=lone[v]
            for i in range(ti+1): out[i][j]=v
            if tj<j:
                for jj in range(tj,j+1): out[ti][jj]=v
            else:
                for jj in range(j,tj+1): out[ti][jj]=v
        else:
            for i in range(h): out[i][j]=v
    return out
