    h, w = len(grid), len(grid[0])
    bar = [j for j, v in enumerate(grid[0]) if v != 0]
    if not bar:
        return [row[:] for row in grid]
    a, b = min(bar), max(bar)
    lone = {}
    for i in range(h):
        for j in range(w):
            v = grid[i][j]
            if v != 0 and not (i == 0 and a <= j <= b):
                lone.setdefault(v, (i, j))
    out = [row[:] for row in grid]
    for j, v in ((j, grid[0][j]) for j in range(a, b + 1)):
        if v in lone:
            ti, tj = lone[v]
            for i in range(ti + 1):
                out[i][j] = v
            lo, hi = sorted((j, tj))
            for jj in range(lo, hi + 1):
                out[ti][jj] = v
        else:
            for i in range(h):
                out[i][j] = v
    return out
